package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;

final class AssetCustodyBrowserAcceptance {
 static void run(BrowserTest h)throws Exception {
  String ci;try(var db=h.store.open()){PlatformFoundationTest.bind(db);Service.createAccount(db,map("name","AssetBrowserKeeper","role","agent","password",WorkflowSupport.PASSWORD));Service.createAccount(db,map("name","AssetBrowserRecipient","role","requester","password",WorkflowSupport.PASSWORD));ci=Service.create(db,"cmdb_ci",map("short_description","Custody workstation"),"admin").get("sys_id").toString();db.connection.commit();}
  try(var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext()){
   var page=context.newPage();h.login(page,"AssetBrowserKeeper");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Asset inventory").setExact(true)).press("Enter");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Create a stockroom")).press("Enter");page.getByLabel("Stockroom name",new Page.GetByLabelOptions().setExact(true)).fill("Tbilisi equipment stock");page.getByLabel("Stockroom location and instructions",new Page.GetByLabelOptions().setExact(true)).fill("Check equipment identity at each handover");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Create record →")).press("Enter");String stock=page.url().substring(page.url().lastIndexOf('/')+1);page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Asset inventory").setExact(true)).press("Enter");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Register an asset")).press("Enter");assertThat(page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Manage asset custody"))).hasCount(0);page.getByLabel("Asset name",new Page.GetByLabelOptions().setExact(true)).fill("Field laptop <script>");page.getByLabel("Asset details",new Page.GetByLabelOptions().setExact(true)).fill("Equipment for service visits");page.locator("input[name=asset_tag]").fill("BROWSER-LAPTOP-001");page.locator("input[name=model]").fill("Portable workstation");page.locator("input[name=serial_number]").fill("BROWSER-SERIAL-001");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Create record →")).press("Enter");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Manage asset custody")).press("Enter");assertThat(page.locator("main")).containsText("No physical receipt has been recorded");page.getByLabel("Receiving stockroom",new Page.GetByLabelOptions().setExact(true)).selectOption(stock);page.getByLabel("Related configuration item",new Page.GetByLabelOptions().setExact(true)).selectOption(ci);page.getByLabel("Receipt or return evidence").fill("Tag and serial checked on physical receipt <script>");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Receive asset into stock")).press("Enter");assertThat(page.locator("main")).containsText("Custody: In stock");page.getByLabel("Recipient username").fill("AssetBrowserRecipient");page.getByLabel("Handover evidence").fill("Recipient acknowledged equipment handover");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Issue asset to recipient")).press("Enter");assertThat(page.locator("main")).containsText("Assigned to: AssetBrowserRecipient");assertThat(page.locator("main")).containsText("Custody: In use");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/asset-issued-light.png")).setFullPage(true));page.getByLabel("Receiving stockroom",new Page.GetByLabelOptions().setExact(true)).selectOption(stock);page.getByLabel("Receipt or return evidence").fill("Returned equipment and accessories checked");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Record asset return")).press("Enter");assertThat(page.locator("main")).not().containsText("Assigned to:");page.getByLabel("Retirement disposition",new Page.GetByLabelOptions().setExact(true)).selectOption("donated");page.getByLabel("Retirement evidence").fill("Custody ended after approved donation and retained handover");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Retire asset").setExact(true)).press("Enter");assertThat(page.locator("main")).containsText("Custody: Retired");assertThat(page.locator("main")).containsText("Movement 4 · retire");assertThat(page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Issue asset to recipient"))).hasCount(0);page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Dark mode").setExact(true)).press("Enter");page.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(page);assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));assertThat(page.locator("main script")).hasCount(0);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/asset-retired-dark.png")).setFullPage(true));
  }
 }
}
